INSERT INTO question_papers (id, slug, title, exam_type, focus_tags, question_count, difficulty, is_premium, sort_order, time_limit_minutes)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2ea5bb17-57cb-44dc-b028-b1f4cef7f1ac', '8c50ddbc-ee33-4a06-8ab3-12685b634e11', 0, 'AWS Systems Manager Parameter Store — stores configuration data and secrets as hierarchically-organized key-value parameters; its Standard tier is free and supports KMS encryption for sensitive values, making it well suited to a mix of non-sensitive configuration and moderately sensitive values at lower cost than Secrets Manager, which is purpose-built specifically for secrets needing automatic ROTATION (like database credentials, covered generally in a prior paper) and charges per secret regardless of sensitivity level.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('862839f0-f486-4648-992f-8668160034a3', '8c50ddbc-ee33-4a06-8ab3-12685b634e11', 1, 'AWS Config, since Config''s core function is storing application configuration values and secrets as key-value parameters for retrieval by applications.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7535828a-b8cf-45d6-a172-b21fa1ca2f93', '8c50ddbc-ee33-4a06-8ab3-12685b634e11', 2, 'AWS CloudTrail, since CloudTrail is the standard service for storing sensitive and non-sensitive application configuration values.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2ce26de5-40b1-49da-a73c-5a7292eb7b8f', '8c50ddbc-ee33-4a06-8ab3-12685b634e11', 3, 'Secrets Manager is the only AWS service capable of storing configuration values or secrets; no lower-cost alternative exists for this need.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b2ce7b61-3d18-4b3f-93f1-dba57db76920', '18b94d7b-bcbf-4f3f-a7ee-6a13a836bcae', 0, 'The `aws:MultiFactorAuthPresent` condition key — an IAM policy condition that evaluates whether the calling principal''s current session was authenticated using MFA, allowing a policy to explicitly require (via a condition on an Allow statement, or an explicit Deny when this condition is false) that a sensitive action can only succeed if MFA was actually used for that specific session, regardless of what other permissions the principal otherwise holds.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ada2bb3d-7900-447e-87f3-c63e486e8610', '18b94d7b-bcbf-4f3f-a7ee-6a13a836bcae', 1, 'The `aws:SourceIp` condition key, since `aws:SourceIp` is specifically defined as evaluating whether a calling principal''s session was authenticated using a second MFA factor.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('78acd869-0fab-461a-af34-f0602702334e', '18b94d7b-bcbf-4f3f-a7ee-6a13a836bcae', 2, 'The `aws:SecureTransport` condition key, since `aws:SecureTransport` is specifically defined as requiring MFA authentication before a sensitive IAM action can succeed.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('16c31a4d-9f4e-4c2e-b96f-bea8b69a942e', '18b94d7b-bcbf-4f3f-a7ee-6a13a836bcae', 3, 'IAM policies have no mechanism for conditionally requiring MFA on a specific action; MFA can only ever be enforced at initial account sign-in, never per-action.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e2491e0d-a7c9-4c33-a8e6-be1c92009855', 'd194dc97-9b4a-41a8-89e1-34f05e3c4f86', 0, 'S3 Access Points — named network endpoints attached to a bucket, each with its own IAM policy scoped to a specific subset of that bucket''s data (e.g., a specific prefix) and its own network permissions, letting each team or application be given its own dedicated, simpler access point rather than every team''s access rules having to be crammed into one single, increasingly complex bucket policy managing the whole bucket at once.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('76bdd14b-9800-4585-9b5b-27c6c2d384cf', 'd194dc97-9b4a-41a8-89e1-34f05e3c4f86', 1, 'S3 Multi-Region Access Points, since Multi-Region Access Points are specifically designed to give each team its own dedicated access configuration for a specific prefix within a single-region bucket.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('73a90994-de89-498f-8b26-17738a681995', 'd194dc97-9b4a-41a8-89e1-34f05e3c4f86', 2, 'S3 Transfer Acceleration, since Transfer Acceleration''s core function is scoping access permissions to a specific prefix for individual teams sharing a bucket.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b2290aad-0ecd-47bb-a58d-cd15e1db2a8c', 'd194dc97-9b4a-41a8-89e1-34f05e3c4f86', 3, 'S3 provides no mechanism for simplifying access management on a bucket shared by multiple teams; a single bucket policy is always the only available option, regardless of complexity.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('eb9e2bcb-815f-4677-bfd3-0690bfe3c4c3', 'a254f759-5dee-46c8-9ad8-d36eca0a3f3f', 0, 'CloudFront Signed URLs (or Signed Cookies) — generates a cryptographically signed, time-limited URL (or cookie, useful when restricting access to MULTIPLE files at once, like an entire video-streaming session''s worth of segments) granting access to specific CloudFront content only for a defined validity window, so content isn''t accessible via a simple, permanently-shareable general URL — access must go through a signed credential issued specifically to an authorized viewer''s session.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('90cb167c-8490-4106-b43c-5e31470761ac', 'a254f759-5dee-46c8-9ad8-d36eca0a3f3f', 1, 'S3 pre-signed URLs, since S3 pre-signed URLs are the standard mechanism for restricting access to content served through a CloudFront distribution specifically.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('56ddfee2-f08c-4d45-b3cf-7b2a00c0e1bd', 'a254f759-5dee-46c8-9ad8-d36eca0a3f3f', 2, 'CloudFront origin groups, since origin groups are specifically designed to generate time-limited, per-session signed URLs restricting access to premium content.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b605e2c4-1d53-4f06-ab1b-b86c3fdb7853', 'a254f759-5dee-46c8-9ad8-d36eca0a3f3f', 3, 'CloudFront has no mechanism to restrict content access to specific authorized users or sessions; all content behind a CloudFront distribution is always freely and permanently accessible to anyone with the distribution URL.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b65a5194-5f63-4c77-974f-72a7d933ef03', '1afb9b13-fbd4-41b5-9f9f-3b29f4812b58', 0, 'AWS Firewall Manager — centrally configures and enforces security policies (WAF rules, Shield Advanced protections, security group policies, and others) consistently across every account and resource in an AWS Organization from ONE place, automatically applying the defined policy even to NEW resources or accounts as they''re created, rather than relying on every individual account/team to independently and correctly configure the same protections on their own.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('df29ed6a-cd7e-4f27-8e73-6cdd3ccb0c6f', '1afb9b13-fbd4-41b5-9f9f-3b29f4812b58', 1, 'AWS Security Hub, since Security Hub''s core function is centrally CONFIGURING and ENFORCING WAF rules, Shield Advanced, and security group policy across an Organization, rather than aggregating findings.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bce005b8-b0a8-4d7e-8432-5ee24486263c', '1afb9b13-fbd4-41b5-9f9f-3b29f4812b58', 2, 'AWS IAM Identity Center, since IAM Identity Center is specifically designed to centrally enforce WAF rules, Shield Advanced protection, and security group policy across an Organization.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5d402665-6d20-4e8b-82bc-ae249c03fe66', '1afb9b13-fbd4-41b5-9f9f-3b29f4812b58', 3, 'No AWS service exists for centrally enforcing security policy across an Organization; every account must always configure WAF, Shield, and security groups entirely independently with no shared mechanism.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ad21c341-22a5-4ebf-b523-1b33380e6b91', 'd385f689-c8bb-499c-b925-49e26e1d30e5', 0, 'Requiring IMDSv2 (and disabling IMDSv1) — IMDSv2 requires a session-oriented request using a PUT-based token before any metadata (including IAM role credentials) can be retrieved, and that initial token-request step specifically cannot be replicated through the kind of simple GET-request SSRF vulnerability that could trivially retrieve credentials under the older IMDSv1 (which allowed a simple GET request with no session token at all), meaningfully closing this specific SSRF-to-credential-theft attack path.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b7e7c5c4-c1b6-434f-8651-6bef7bf65889', 'd385f689-c8bb-499c-b925-49e26e1d30e5', 1, 'Enabling EBS optimization on the instance, since EBS optimization is the setting that specifically hardens the Instance Metadata Service against SSRF-based credential theft.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c3b0be74-700e-45a3-a1bc-44b4b2aed5f6', 'd385f689-c8bb-499c-b925-49e26e1d30e5', 2, 'Placing the instance in a Placement Group, since Placement Groups are the mechanism that specifically hardens IMDS against SSRF-based IAM credential theft.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('660868d7-0827-43f4-a4a0-b38ae0c1e5a3', 'd385f689-c8bb-499c-b925-49e26e1d30e5', 3, 'The Instance Metadata Service has no known SSRF-related exposure and requires no hardening or configuration change of any kind.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9da2c97f-e0b3-4eb3-b5d6-01ed810a9c02', 'b855fbea-f171-4eb2-be37-156cff0b4adb', 0, 'Yes — S3 replication (whether Same-Region or Cross-Region Replication, both covered generally in prior papers) fully supports replicating to a bucket owned by a different AWS account, which requires the DESTINATION bucket''s owner to grant explicit permission via a bucket policy (or an S3 Batch Operations/replication-specific IAM role configuration) authorizing the source account to replicate objects into it, and typically involves specifying object ownership so replicated objects are correctly owned by the destination account rather than remaining owned by the source account.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4789c005-13c1-48f9-b0d1-b296d39a989c', 'b855fbea-f171-4eb2-be37-156cff0b4adb', 1, 'No — S3 replication can only ever replicate to a bucket owned by the exact same AWS account as the source bucket, with cross-account replication being technically impossible.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5f6aecca-496a-4328-a846-c31ffd3143eb', 'b855fbea-f171-4eb2-be37-156cff0b4adb', 2, 'Cross-account S3 replication requires no additional configuration beyond same-account replication; the destination account''s bucket owner has no ability to control or restrict this replicated access.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f93cec0b-edda-477f-9ba3-d50d9465623f', 'b855fbea-f171-4eb2-be37-156cff0b4adb', 3, 'S3 replication to a different account is only possible using S3 Multi-Region Access Points, with no other mechanism available.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2a0e55cd-dadf-4fba-b39b-c4dbccd44b1d', 'd0eee210-0591-4301-b011-3415cdd40584', 0, 'RDS Multi-AZ DB Cluster deployment — maintains TWO readable standby instances (rather than classic Multi-AZ''s single, non-readable-until-failover standby), typically achieving faster failover (often under a minute, meaningfully quicker than classic Multi-AZ''s roughly one-to-two-minute failover, covered generally in a prior paper) using a quorum-based mechanism, while ALSO allowing read traffic to be offloaded to those standby instances during normal operation rather than leaving that standby capacity completely idle outside of an actual failover event.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dc892c50-83ba-4da4-bb6c-1ab38a88a63d', 'd0eee210-0591-4301-b011-3415cdd40584', 1, 'Classic RDS Multi-AZ (single standby) deployment, since classic Multi-AZ is specifically defined as providing two readable standby instances with faster, quorum-based failover.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e4ca4546-cc34-4abd-ad1a-e3d3f6b2678d', 'd0eee210-0591-4301-b011-3415cdd40584', 2, 'RDS Read Replicas, since Read Replicas are specifically defined as providing automatic, quorum-based failover with sub-minute recovery time.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7b620920-8f22-47a2-839c-c9cd46ee954f', 'd0eee210-0591-4301-b011-3415cdd40584', 3, 'RDS offers no deployment option providing both faster-than-classic-Multi-AZ failover and a readable standby; these two characteristics can never be achieved together.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b1bc9b93-697b-4afb-b676-45a31ffeca83', '00783c98-7c36-44f6-a885-6c8accd2d7d5', 0, 'ASG Warm Pools — maintains a pool of pre-initialized (but not actively serving live traffic) instances in a stopped or running state, ready to be quickly transitioned into active service when the Auto Scaling Group actually needs to scale out, meaningfully reducing the delay between "scaling decision triggered" and "instance genuinely ready to serve traffic" compared to launching and fully initializing a brand-new instance from scratch at the moment of the scaling event.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('283eab80-ff2f-452a-a288-8a5922b02795', '00783c98-7c36-44f6-a885-6c8accd2d7d5', 1, 'ASG Lifecycle Hooks, since Lifecycle Hooks are specifically defined as maintaining a pool of pre-initialized instances ready to be quickly moved into active service.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8d4fb44d-8fe7-4eb2-b2c4-eae61965fb73', '00783c98-7c36-44f6-a885-6c8accd2d7d5', 2, 'ASG Scheduled Scaling, since Scheduled Scaling is the feature that keeps a standby pool of pre-initialized instances ready for rapid activation during unplanned traffic spikes.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8e19f711-5324-49cf-a2d0-db0b7d21cfe5', '00783c98-7c36-44f6-a885-6c8accd2d7d5', 3, 'No ASG feature exists to reduce the delay between a scaling decision and an instance actually being ready to serve traffic; every newly launched instance must always fully initialize from scratch with no way to pre-warm capacity.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dce0c1d0-2996-4bfd-b130-26b5ba90aff5', 'a7240e78-40be-4fb5-a2c3-7505f06ae1ee', 0, 'Last writer wins — DynamoDB Global Tables resolve concurrent, conflicting updates to the same item across Regions by keeping whichever write has the LATEST timestamp, with the earlier-timestamped concurrent write from the other Region being discarded; this is a genuinely important architectural characteristic to understand before choosing Global Tables for a workload, since an application with a real risk of frequent concurrent same-item updates across Regions needs to be designed with this specific conflict-resolution behavior (and the possibility of a write being silently overwritten by a concurrent one) in mind.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('babc90e7-107e-4855-80f5-273362c92642', 'a7240e78-40be-4fb5-a2c3-7505f06ae1ee', 1, 'DynamoDB Global Tables reject BOTH concurrent updates entirely and require the application to manually resolve every conflict before either write is ever applied.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('48a27ffd-34a8-4522-ad7d-d39d82d79bc3', 'a7240e78-40be-4fb5-a2c3-7505f06ae1ee', 2, 'DynamoDB Global Tables merge both concurrent updates'' field-level changes together automatically, regardless of which fields were actually modified by each write.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1de494ed-76f8-4035-84ef-b027c5cd6d6f', 'a7240e78-40be-4fb5-a2c3-7505f06ae1ee', 3, 'Concurrent updates to the same item across different Regions can never actually occur with DynamoDB Global Tables, since writes are always fully serialized globally in real time.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5564632c-6487-498c-b565-5d6a551a63d0', '5d2cb9f9-8a80-4b68-8764-343a13acf5c1', 0, 'AWS Backup Vault Lock — applies WORM (Write Once, Read Many) immutability specifically to an entire AWS Backup vault, preventing backups stored in that vault from being deleted or having their retention period shortened by ANYONE — including the account''s own administrators, once the vault lock is placed in compliance mode — for the duration of the defined minimum retention period, directly protecting backups against exactly the "compromised or malicious administrator credential" scenario that a normal IAM-permission-based protection alone couldn''t fully close.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8b6001c8-5b75-4124-8dc5-14d3d7dfa87f', '5d2cb9f9-8a80-4b68-8764-343a13acf5c1', 1, 'S3 Object Lock, since S3 Object Lock is itself the AWS Backup feature that applies WORM immutability directly to an AWS Backup vault.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5321d443-420a-44f6-a452-7827e659883b', '5d2cb9f9-8a80-4b68-8764-343a13acf5c1', 2, 'AWS Elastic Disaster Recovery, since AWS DRS is the feature that applies WORM immutability to backups stored in an AWS Backup vault.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a9fd590a-5663-4b7f-bbe0-14285cde2580', '5d2cb9f9-8a80-4b68-8764-343a13acf5c1', 3, 'AWS Backup provides no mechanism to prevent a sufficiently privileged administrator credential from deleting or modifying a stored backup under any circumstance.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('14378a31-52de-4c5c-888a-055639274259', '342d9f81-46a7-4459-a057-3c7386e28fd6', 0, 'Regional Edge Caches — an intermediate caching tier, automatically used by CloudFront (with no additional configuration required, distinct from the OPT-IN Origin Shield feature covered generally in a prior paper), sitting between individual edge locations and the origin; a cache miss at an edge location first checks the nearer Regional Edge Cache (which has a larger cache size and therefore a higher likelihood of already holding the content) before falling through to the origin, increasing the overall cache-hit rate across the network and reducing origin load.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('48a4809b-0e6b-4955-befc-2fd0a5c69fb6', '342d9f81-46a7-4459-a057-3c7386e28fd6', 1, 'Origin Shield, since Origin Shield is defined as an automatic, no-configuration-required intermediate caching tier used by every CloudFront distribution by default.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d30ab17e-c565-424a-adf4-0610064d023c', '342d9f81-46a7-4459-a057-3c7386e28fd6', 2, 'CloudFront origin groups, since origin groups are defined as an intermediate caching tier sitting between edge locations and the origin server.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9a11e212-9cda-424b-a133-8cb4226d8034', '342d9f81-46a7-4459-a057-3c7386e28fd6', 3, 'CloudFront has no intermediate caching tier of any kind; every cache miss at an edge location always goes directly to the origin with no intermediate step.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1a0b8d1f-fa9b-4516-bf40-4110d2209662', '0ba9ea67-1802-4bc4-b036-1bf15ef25b57', 0, 'DynamoDB adaptive capacity — automatically and continuously monitors for uneven traffic distribution across a table''s partitions, and dynamically shifts throughput capacity toward partitions experiencing disproportionately high traffic, helping absorb temporary, uneven "hot" access patterns without manual intervention; this doesn''t eliminate the value of good partition key DESIGN for genuinely sustained, predictable hot-partition patterns (covered generally in a prior paper), but does meaningfully help absorb SHORTER-TERM, less predictable traffic spikes automatically.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('64048f00-182c-4843-a40f-9654fa975047', '0ba9ea67-1802-4bc4-b036-1bf15ef25b57', 1, 'DynamoDB Accelerator (DAX), since DAX is specifically defined as automatically redistributing write throughput capacity toward temporarily hot partitions.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('091f3639-0a56-4bfd-a073-7b71ac158d04', '0ba9ea67-1802-4bc4-b036-1bf15ef25b57', 2, 'DynamoDB Global Tables, since Global Tables are the feature that automatically redistributes throughput capacity toward temporarily hot partitions within a single table.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0248bcee-77cf-42ac-974a-1c8022dbd444', '0ba9ea67-1802-4bc4-b036-1bf15ef25b57', 3, 'DynamoDB has no automatic mechanism for handling uneven partition traffic; redesigning the partition key is always the only available response to any hot-partition scenario.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('19d56b2e-ecec-48fa-8a19-8fa8d01d825d', '629aa1ce-64f7-46d6-9b64-8bfebfea4fd0', 0, 'ALB path-based and host-based routing rules — an Application Load Balancer evaluates configurable LISTENER RULES against each incoming request''s URL path (e.g., `/api/*` vs. `/images/*`) and/or HTTP Host header (e.g., `images.example.com`), routing each request to a DIFFERENT target group based on which rule matches, letting a single ALB efficiently serve multiple distinct backend components or even multiple different applications, rather than needing a separate load balancer for each individual component.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f4715a6e-0c2f-4a78-97f9-e5233dc99bee', '629aa1ce-64f7-46d6-9b64-8bfebfea4fd0', 1, 'A Network Load Balancer, since NLBs are specifically defined as routing requests to different target groups based on URL path or HTTP hostname.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0d8dc113-77e4-4d79-a1dc-8826446fd326', '629aa1ce-64f7-46d6-9b64-8bfebfea4fd0', 2, 'CloudFront origin groups, since origin groups are the feature that routes requests to different backend target groups based on URL path or hostname.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fbbb1937-bfe4-40b9-ad9f-bc72d31a0e10', '629aa1ce-64f7-46d6-9b64-8bfebfea4fd0', 3, 'An Application Load Balancer can only ever route every request to a single target group; routing different request paths or hostnames to different target groups is not possible.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7b0e8026-85a3-422e-b2c5-fd03bd967411', '213d181f-b6e8-4465-a517-8dc4f869af98', 0, 'EC2 Hibernate — saves the contents of the instance''s RAM to its root EBS volume when the instance is stopped, and restores that exact in-memory state (including a warmed application cache, open files, and running process state) when the instance is subsequently started again, rather than performing a normal cold boot that would require re-warming any in-memory state from scratch — meaningfully different from a standard EC2 stop/start, which does NOT preserve RAM contents at all.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0e3173b8-1340-47f2-8720-bfad03c821fc', '213d181f-b6e8-4465-a517-8dc4f869af98', 1, 'A standard EC2 stop and start, since standard stop/start is specifically defined as preserving the instance''s full RAM contents, including a warmed in-memory cache, across the stop/start cycle.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e4aee7e1-3ad0-4f36-8ea8-41542e38ecba', '213d181f-b6e8-4465-a517-8dc4f869af98', 2, 'EC2 auto-recovery, since auto-recovery is the feature that preserves an instance''s RAM contents across a stop and subsequent restart.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9c1990f5-c935-4e57-aa42-a6bd302dd4c8', '213d181f-b6e8-4465-a517-8dc4f869af98', 3, 'EC2 provides no mechanism to preserve an instance''s in-memory state across a stop/start cycle; RAM contents are always completely lost whenever an instance is stopped, with no exception.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6ee6b72f-d4a6-4347-a6c5-957750820155', 'bcb4249c-0e51-4320-9110-a2ea2f506bf3', 0, 'Yes, by default — Reserved Instance (and Savings Plans) discounts automatically apply across ALL member accounts within the same AWS Organization under Consolidated Billing, not just the specific account that purchased the reservation, so if a different member account has matching, otherwise-unused instance usage, the existing RI''s discount is automatically applied to that usage rather than the discount going to waste in the purchasing account (this default sharing behavior can be selectively disabled per account if an organization specifically wants to restrict it).');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b8d216c4-3311-427a-8ed6-9c91c911878e', 'bcb4249c-0e51-4320-9110-a2ea2f506bf3', 1, 'No — Reserved Instance discounts are always strictly confined to the exact account that purchased the reservation, with no possibility of sharing the discount across other member accounts under any circumstance.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e747f287-2624-46ca-ab8a-c2d85d9efb89', 'bcb4249c-0e51-4320-9110-a2ea2f506bf3', 2, 'Reserved Instance discounts can only ever be shared across accounts by physically transferring the underlying EC2 instance itself between accounts.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('906e921a-c36d-42d9-97c1-4aba30564227', 'bcb4249c-0e51-4320-9110-a2ea2f506bf3', 3, 'RI discount sharing across accounts requires a separate, additional AWS service subscription beyond standard AWS Organizations Consolidated Billing.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3090ac8a-57b2-46c9-a3ab-dab36cbc8256', '5cea947d-ede8-4c57-b4cd-59dc839b2167', 0, 'On-Demand Capacity Reservations (ODCR) — reserves EC2 capacity of a specific instance type/size in a specific Availability Zone, guaranteeing that capacity will genuinely be available when needed, WITHOUT requiring any long-term 1- or 3-year commitment — billed at the standard On-Demand rate for the duration the reservation is held (with no billing discount of its own, since ODCRs address CAPACITY ASSURANCE specifically, not cost reduction), and can be created and canceled flexibly to match a short-term need like a specific event window.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1e55d45e-80e5-463e-84b5-ef6d5cdc4001', '5cea947d-ede8-4c57-b4cd-59dc839b2167', 1, 'A Standard Reserved Instance, since Standard RIs are specifically designed to guarantee short-term, event-specific capacity availability without any 1- or 3-year commitment requirement.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b98c0220-8222-4de9-8981-32c1590fd85b', '5cea947d-ede8-4c57-b4cd-59dc839b2167', 2, 'A Spot Instance, since Spot Instances are specifically designed to provide a guaranteed capacity availability commitment for a specific, time-sensitive event.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2d4bc058-5063-411c-9bf8-11c62e1ed536', '5cea947d-ede8-4c57-b4cd-59dc839b2167', 3, 'No EC2 mechanism exists to guarantee capacity availability for a short-term need without also requiring a long-term 1- or 3-year commitment.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ffef9c4f-744d-4d8e-ab11-14d9cc7ca222', '29bc305f-4b34-4346-9268-a72ca1e4b1ba', 0, 'A self-managed NAT instance can be cheaper (particularly at low, steady traffic volumes, since it''s billed as a regular EC2 instance rather than incurring NAT Gateway''s specific hourly-plus-per-GB pricing), but the trade-off is real, meaningful OPERATIONAL burden and reduced resilience: the company itself must patch, monitor, and manage that instance''s availability and scaling (a NAT Gateway is fully managed by AWS, requiring none of this), a single NAT instance is a genuine bottleneck/single point of failure unless additional HA architecture is separately built around it, and it generally cannot match a NAT Gateway''s bandwidth scaling ceiling for genuinely high-throughput workloads.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d7efc8b9-b259-4ab5-85bb-face7c58f4d0', '29bc305f-4b34-4346-9268-a72ca1e4b1ba', 1, 'A NAT instance and a NAT Gateway are functionally and operationally identical in every respect, including management burden, resilience, and bandwidth scaling, with no meaningful trade-off between them.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c99a7deb-c75e-47a5-a277-770cff24b2c9', '29bc305f-4b34-4346-9268-a72ca1e4b1ba', 2, 'A NAT instance is always more expensive than a NAT Gateway under every possible traffic volume, making a NAT instance never a reasonable cost-optimization choice under any circumstance.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('962baf71-396f-4dd2-85f8-71430c72abb4', '29bc305f-4b34-4346-9268-a72ca1e4b1ba', 3, 'AWS provides no option other than a managed NAT Gateway for private-subnet outbound internet connectivity; a self-managed NAT instance is not a real, available alternative.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('efbfe7b8-0662-4594-8f96-6a8c20bccc51', 'e570c979-f951-4677-9263-d39049321e94', 0, 'An S3 Lifecycle rule specifically targeting incomplete multipart uploads — configures S3 to automatically abort and delete the stored parts of any multipart upload that hasn''t been completed (or explicitly aborted) within a configurable number of days, directly preventing this genuinely easy-to-overlook cost leak, where abandoned upload parts from failed or interrupted uploads would otherwise continue accumulating storage charges indefinitely with no automatic cleanup.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('df96cfd9-4d52-447f-b05f-86e85ec0b68d', 'e570c979-f951-4677-9263-d39049321e94', 1, 'S3 Versioning, since S3 Versioning is the specific feature that automatically aborts and cleans up incomplete, abandoned multipart uploads after a configurable period.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2c43cc7d-35b1-4738-aba0-fc62db149add', 'e570c979-f951-4677-9263-d39049321e94', 2, 'S3 Storage Class Analysis, since Storage Class Analysis automatically aborts and deletes the stored parts of incomplete multipart uploads.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('32977f7f-1b95-4f04-a8fd-60dfc7895f2c', 'e570c979-f951-4677-9263-d39049321e94', 3, 'Incomplete multipart upload parts are automatically deleted by S3 within 24 hours with no configuration or lifecycle rule required.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2aeda7ff-a76f-4be9-a31b-8b7e8cd644b9', '6126ae79-0c2e-4ca1-a008-6eaa18d9a42d', 0, 'Aurora Parallel Query — pushes portions of a large-scan analytical query''s processing (filtering and aggregation work) DOWN into Aurora''s distributed storage layer itself, executing that work in PARALLEL across the storage nodes rather than sequentially in the single database compute instance, meaningfully speeding up exactly the kind of large-table-scan, aggregation-heavy analytical query described, by distributing the actual scanning/filtering work rather than pulling all the raw data up to the compute layer to process serially there.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c52b8999-bbe7-4e15-b6c9-c865cbad1a05', '6126ae79-0c2e-4ca1-a008-6eaa18d9a42d', 1, 'Aurora Backtrack, since Aurora Backtrack is specifically defined as pushing large-scan analytical query processing down into the storage layer for parallel execution.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dcf35ec5-699d-4033-966a-adaab1a367b9', '6126ae79-0c2e-4ca1-a008-6eaa18d9a42d', 2, 'Aurora Global Database, since Aurora Global Database''s core function is executing large-scan analytical queries in parallel at the storage layer within a single Region.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d2ab38f8-10cd-426e-b0d9-610b957e6766', '6126ae79-0c2e-4ca1-a008-6eaa18d9a42d', 3, 'Aurora has no mechanism for accelerating large-scan analytical queries beyond what a standard read replica (covered generally in a prior paper) already provides for read scaling.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
